169	    pub fn load_loss_governor_manual_recoveries(
170	        &self,
171	    ) -> Result<Vec<KillSwitchLossGovernorManualRecoveryRecord>, KillSwitchStoreError> {
172	        let audit_path = self.loss_governor_manual_recovery_audit_path();
173	        let contents = match fs::read_to_string(&audit_path) {
174	            Ok(contents) => contents,
175	            Err(source) if source.kind() == io::ErrorKind::NotFound => return Ok(Vec::new()),
176	            Err(source) => {
177	                return Err(KillSwitchStoreError::Io {
178	                    path: audit_path,
179	                    source,
180	                });
181	            }
182	        };
183	        let lines: Vec<&str> = contents.lines().collect();
184	        let final_line_index = lines.len().saturating_sub(1);
185	        let mut records = Vec::new();
186	        for (line_index, line) in lines.into_iter().enumerate() {
187	            if line.trim().is_empty() {
188	                continue;
189	            }
190	            match serde_json::from_str(line) {
191	                Ok(record) => records.push(record),
192	                Err(source) if line_index == final_line_index && !contents.ends_with('\n') => {
193	                    log::error!(
194	                        "skipping unparseable final loss-governor manual recovery audit line in {}: {source}",
195	                        audit_path.display()
196	                    );
197	                }
198	                Err(source) => {
199	                    return Err(KillSwitchStoreError::Deserialize {
200	                        path: audit_path.clone(),
201	                        source,
202	                    });
203	                }
204	            }
205	        }
206	        Ok(records)
207	    }
