209	    fn loss_governor_manual_recovery_audit_appendable_line_count(
210	        &self,
211	    ) -> Result<usize, KillSwitchStoreError> {
212	        let audit_path = self.loss_governor_manual_recovery_audit_path();
213	        let mut file = match fs::File::open(&audit_path) {
214	            Ok(file) => file,
215	            Err(source) if source.kind() == io::ErrorKind::NotFound => return Ok(0),
216	            Err(source) => {
217	                return Err(KillSwitchStoreError::Io {
218	                    path: audit_path,
219	                    source,
220	                });
221	            }
222	        };
223	        let file_len = file
224	            .metadata()
225	            .map_err(|source| KillSwitchStoreError::Io {
226	                path: audit_path.clone(),
227	                source,
228	            })?
229	            .len();
230	        if file_len == 0 {
231	            return Ok(0);
232	        }
233	        file.seek(SeekFrom::End(-1))
234	            .map_err(|source| KillSwitchStoreError::Io {
235	                path: audit_path.clone(),
236	                source,
237	            })?;
238	        let mut last_byte = [0_u8; 1];
239	        file.read_exact(&mut last_byte)
240	            .map_err(|source| KillSwitchStoreError::Io {
241	                path: audit_path.clone(),
242	                source,
243	            })?;
244	        if last_byte[0] != b'\n' {
245	            log::error!(
246	                "refusing to append loss-governor manual recovery audit line because {} does not end with a newline",
247	                audit_path.display()
248	            );
249	            return Err(KillSwitchStoreError::TornManualRecoveryAudit { path: audit_path });
250	        }
251	        file.seek(SeekFrom::Start(0))
252	            .map_err(|source| KillSwitchStoreError::Io {
253	                path: audit_path.clone(),
254	                source,
255	            })?;
256	        let reader = io::BufReader::new(file);
257	        let mut count = 0;
258	        for line in reader.lines() {
259	            let line = line.map_err(|source| KillSwitchStoreError::Io {
260	                path: audit_path.clone(),
261	                source,
262	            })?;
263	            if !line.trim().is_empty() {
264	                count += 1;
265	            }
266	        }
267	        Ok(count)
268	    }
