346	        }
347	
348	        let persisted = match serde_json::from_slice::<PersistedKillSwitchState>(&bytes) {
349	            Ok(persisted) => persisted,
350	            Err(_) => {
351	                return Ok(KillSwitchRecoveryRecord {
352	                    recovery_state: KillSwitchRecoveryState::FailClosed {
353	                        reason: KillSwitchRecoveryReason::CorruptEvidence,
354	                        state: None,
355	                    },
356	                    loss_protection: None,
357	                });
358	            }
359	        };
360	
361	        if persisted.schema_version != KILL_SWITCH_STORE_SCHEMA_VERSION {
362	            return Ok(KillSwitchRecoveryRecord {
363	                recovery_state: KillSwitchRecoveryState::FailClosed {
364	                    reason: KillSwitchRecoveryReason::UnsupportedSchemaVersion,
365	                    state: Some(persisted.state),
366	                },
367	                loss_protection: None,
368	            });
369	        }
370	
371	        let loss_protection = match persisted.loss_protection {
372	            Some(snapshot) => match KillSwitchLossProtectionSnapshot::try_from(snapshot) {
373	                Ok(snapshot) => Some(snapshot),
374	                Err(()) => {
375	                    return Ok(KillSwitchRecoveryRecord {
376	                        recovery_state: KillSwitchRecoveryState::FailClosed {
377	                            reason: KillSwitchRecoveryReason::CorruptEvidence,
378	                            state: Some(persisted.state),
379	                        },
380	                        loss_protection: None,
381	                    });
382	                }
383	            },
384	            None => None,
385	        };
386	
387	        let recovery_state = match persisted.state {
388	            KillSwitchState::Halting { .. } | KillSwitchState::FailedManualIntervention { .. } => {
389	                KillSwitchRecoveryState::FailClosed {
390	                    reason: KillSwitchRecoveryReason::UnresolvedHalt,
391	                    state: Some(persisted.state),
392	                }
393	            }
394	            state => KillSwitchRecoveryState::Recovered(state),
395	        };
396	        Ok(KillSwitchRecoveryRecord {
397	            recovery_state,
398	            loss_protection,
399	        })
400	    }
401	}
