403	pub fn initial_armed_loss_protection_snapshot() -> KillSwitchLossProtectionSnapshot {
404	    KillSwitchLossProtectionSnapshot {
405	        daily_bucket: None,
406	        daily_realized_pnl: Decimal::ZERO,
407	        settlement_currency: None,
408	        cumulative_position_pnl: BTreeMap::new(),
409	        closed_position_pnl: BTreeMap::new(),
410	        adjusted_position_pnl: BTreeMap::new(),
411	        pending_halt_actions: None,
412	    }
413	}
