415	fn serialize_state_with_loss_snapshot(
416	    state: &KillSwitchState,
417	    loss_protection: Option<&KillSwitchLossProtectionSnapshot>,
418	) -> Result<Vec<u8>, KillSwitchStoreError> {
419	    let persisted = PersistedKillSwitchState {
420	        schema_version: KILL_SWITCH_STORE_SCHEMA_VERSION,
421	        state: state.clone(),
422	        loss_protection: loss_protection.map(PersistedKillSwitchLossProtectionSnapshot::from),
423	    };
424	    let mut bytes =
425	        serde_json::to_vec_pretty(&persisted).map_err(KillSwitchStoreError::Serialize)?;
426	    bytes.push(b'\n');
427	    Ok(bytes)
428	}
