430	#[derive(Debug, Serialize, Deserialize)]
431	struct PersistedKillSwitchState {
432	    schema_version: u32,
433	    state: KillSwitchState,
434	    #[serde(skip_serializing_if = "Option::is_none")]
435	    loss_protection: Option<PersistedKillSwitchLossProtectionSnapshot>,
436	}
