439	struct PersistedKillSwitchLossProtectionSnapshot {
440	    daily_bucket: Option<u64>,
441	    daily_realized_pnl: String,
442	    #[serde(skip_serializing_if = "Option::is_none")]
443	    settlement_currency: Option<String>,
444	    cumulative_position_pnl: BTreeMap<String, PersistedCumulativePositionPnlSnapshot>,
445	    closed_position_pnl: BTreeMap<String, PersistedCumulativePositionPnlSnapshot>,
446	    adjusted_position_pnl: BTreeMap<String, PersistedCumulativePositionPnlSnapshot>,
447	    #[serde(skip_serializing_if = "Option::is_none")]
