451	#[derive(Debug, Serialize, Deserialize)]
452	struct PersistedCumulativePositionPnlSnapshot {
453	    realized_pnl: String,
454	    last_observed_at_unix_nanos: u64,
455	}
456	
457	fn persist_pnl_map(
458	    map: &BTreeMap<String, KillSwitchCumulativePositionPnlSnapshot>,
459	) -> BTreeMap<String, PersistedCumulativePositionPnlSnapshot> {
460	    map.iter()
461	        .map(|(position_id, value)| {
462	            (
463	                position_id.clone(),
464	                PersistedCumulativePositionPnlSnapshot {
465	                    realized_pnl: value.realized_pnl.to_string(),
466	                    last_observed_at_unix_nanos: value.last_observed_at_unix_nanos,
467	                },
468	            )
469	        })
470	        .collect()
471	}
472	
473	fn restore_pnl_map(
474	    map: BTreeMap<String, PersistedCumulativePositionPnlSnapshot>,
475	) -> Result<BTreeMap<String, KillSwitchCumulativePositionPnlSnapshot>, ()> {
476	    let mut restored = BTreeMap::new();
477	    for (position_id, value) in map {
478	        restored.insert(
479	            position_id,
480	            KillSwitchCumulativePositionPnlSnapshot {
481	                realized_pnl: Decimal::from_str(&value.realized_pnl).map_err(|_| ())?,
482	                last_observed_at_unix_nanos: value.last_observed_at_unix_nanos,
483	            },
484	        );
485	    }
486	    Ok(restored)
487	}
