489	impl From<&KillSwitchLossProtectionSnapshot> for PersistedKillSwitchLossProtectionSnapshot {
490	    fn from(snapshot: &KillSwitchLossProtectionSnapshot) -> Self {
491	        Self {
492	            daily_bucket: snapshot.daily_bucket,
493	            daily_realized_pnl: snapshot.daily_realized_pnl.to_string(),
494	            settlement_currency: snapshot.settlement_currency.clone(),
495	            cumulative_position_pnl: persist_pnl_map(&snapshot.cumulative_position_pnl),
496	            closed_position_pnl: persist_pnl_map(&snapshot.closed_position_pnl),
497	            adjusted_position_pnl: persist_pnl_map(&snapshot.adjusted_position_pnl),
498	            pending_halt_actions: snapshot.pending_halt_actions,
499	        }
500	    }
501	}
