503	impl TryFrom<PersistedKillSwitchLossProtectionSnapshot> for KillSwitchLossProtectionSnapshot {
504	    type Error = ();
505	
506	    fn try_from(snapshot: PersistedKillSwitchLossProtectionSnapshot) -> Result<Self, Self::Error> {
507	        let daily_realized_pnl = Decimal::from_str(&snapshot.daily_realized_pnl).map_err(|_| ())?;
508	        let cumulative_position_pnl = restore_pnl_map(snapshot.cumulative_position_pnl)?;
509	        let closed_position_pnl = restore_pnl_map(snapshot.closed_position_pnl)?;
510	        if cumulative_position_pnl
511	            .keys()
512	            .any(|position_id| closed_position_pnl.contains_key(position_id))
513	        {
514	            return Err(());
515	        }
516	        let adjusted_position_pnl = restore_pnl_map(snapshot.adjusted_position_pnl)?;
517	        let has_loss_evidence = daily_realized_pnl != Decimal::ZERO
518	            || !cumulative_position_pnl.is_empty()
519	            || !closed_position_pnl.is_empty()
520	            || !adjusted_position_pnl.is_empty();
521	        let settlement_currency = match snapshot.settlement_currency {
522	            Some(currency) if currency.trim().is_empty() || currency.trim() != currency => {
523	                return Err(());
524	            }
525	            Some(currency) if Currency::try_from_str(&currency).is_none() => {
526	                return Err(());
527	            }
528	            Some(currency) => Some(currency),
529	            None if has_loss_evidence => return Err(()),
530	            None => None,
531	        };
532	        Ok(Self {
533	            daily_bucket: snapshot.daily_bucket,
534	            daily_realized_pnl,
535	            settlement_currency,
536	            cumulative_position_pnl,
537	            closed_position_pnl,
538	            adjusted_position_pnl,
539	            pending_halt_actions: snapshot.pending_halt_actions,
540	        })
541	    }
542	}
