569	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
570	        match self {
571	            Self::Io { path, source } => {
572	                write!(f, "failed to access {}: {source}", path.display())
573	            }
574	            Self::Serialize(error) => write!(f, "failed to serialize kill-switch state: {error}"),
575	            Self::Deserialize { path, source } => {
